import{_ as p,a0 as r,w as o,s as d,ao as l,I as t,x as a,a1 as i,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"在 Linux 上如何得到一個段錯誤的核心轉儲 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上如何得到一個段錯誤的核心轉儲 | LCTT (201807) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上如何得到一個段錯誤的核心轉儲 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上如何得到一個段錯誤的核心轉儲 | LCTT (201807) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201807/20180428 How to get a core dump for a segfault on Linux","title":"在 Linux 上如何得到一個段錯誤的核心轉儲","tag":"201807","desc":""},"relativePath":"201807/20180428 How to get a core dump for a segfault on Linux.md","filePath":"[post].md"}'),c={name:"201807/20180428 How to get a core dump for a segfault on Linux.md"};function u(b,e,h,g,m,k){const s=r("Link");return o(),d("div",null,[e[20]||(e[20]=l(`<h1 id="在-linux-上如何得到一個段錯誤的核心轉儲" tabindex="-1">在 Linux 上如何得到一個段錯誤的核心轉儲 <a class="header-anchor" href="#在-linux-上如何得到一個段錯誤的核心轉儲" aria-label="Permalink to “在 Linux 上如何得到一個段錯誤的核心轉儲”">​</a></h1><p>本週工作中，我花了整整一週的時間來嘗試調試一個段錯誤。我以前從來沒有這樣做過，我花了很長時間才弄清楚其中涉及的一些基本事情（獲得核心轉儲、找到導致段錯誤的行號）。於是便有了這篇Blog來解釋如何做那些事情！</p><p>在看完這篇Blog後，你應該知道如何從“哦，我的程序出現段錯誤，但我不知道正在發生什麼”到“我知道它出現段錯誤時的堆棧、行號了！ “。</p><h3 id="什麼是段錯誤" tabindex="-1">什麼是段錯誤？ <a class="header-anchor" href="#什麼是段錯誤" aria-label="Permalink to “什麼是段錯誤？”">​</a></h3><p>“<ruby>段錯誤<rt>segmentation fault</rt></ruby>”是指你的程序嘗試訪問不允許訪問的內存地址的情況。這可能是由於：</p><ul><li>試圖解引用空指針（你不被允許訪問內存地址 <code>0</code>）；</li><li>試圖解引用其他一些不在你內存（LCTT 譯註：指不在合法的內存地址區間內）中的指針；</li><li>一個已被破壞並且指向錯誤的地方的 <ruby>C++ 虛表指針<rt>C++ vtable pointer</rt></ruby>，這導致程序嘗試執行沒有執行權限的內存中的指令；</li><li>其他一些我不明白的事情，比如我認為訪問未對齊的內存地址也可能會導致段錯誤（LCTT 譯註：在要求自然邊界對齊的體系結構，如 MIPS、ARM 中更容易因非對齊訪問產生段錯誤）。</li></ul><p>這個“C++ 虛表指針”是我的程序發生段錯誤的情況。我可能會在未來的Blog中解釋這個，因為我最初並不知道任何關於 C++ 的知識，並且這種虛表查找導致程序段錯誤的情況也是我所不瞭解的。</p><p>但是！這篇Blog後不是關於 C++ 問題的。讓我們談論的基本的東西，比如，我們如何得到一個核心轉儲？</p><h3 id="步驟1-運行-valgrind" tabindex="-1">步驟1：運行 valgrind <a class="header-anchor" href="#步驟1-運行-valgrind" aria-label="Permalink to “步驟1：運行 valgrind”">​</a></h3><p>我發現找出為什麼我的程序出現段錯誤的最簡單的方式是使用 <code>valgrind</code>：我運行</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>valgrind -v your-program</span></span></code></pre></div><p>這給了我一個故障時的堆棧調用序列。 簡潔！</p><p>但我想也希望做一個更深入調查，並找出些 <code>valgrind</code> 沒告訴我的信息！ 所以我想獲得一個核心轉儲並探索它。</p><h3 id="如何獲得一個核心轉儲" tabindex="-1">如何獲得一個核心轉儲 <a class="header-anchor" href="#如何獲得一個核心轉儲" aria-label="Permalink to “如何獲得一個核心轉儲”">​</a></h3><p><ruby>核心轉儲<rt>core dump</rt></ruby>是您的程序內存的一個副本，並且當您試圖調試您的有問題的程序哪裏出錯的時候它非常有用。</p><p>當您的程序出現段錯誤，Linux 的內核有時會把一個核心轉儲寫到磁盤。 當我最初試圖獲得一個核心轉儲時，我很長一段時間非常沮喪，因為 - Linux 沒有生成核心轉儲！我的核心轉儲在哪裏？</p><p>這就是我最終做的事情：</p><ol><li>在啓動我的程序之前運行 <code>ulimit -c unlimited</code></li><li>運行 <code>sudo sysctl -w kernel.core_pattern=/tmp/core-%e.%p.%h.%t</code></li></ol><h3 id="ulimit-設置核心轉儲的最大尺寸" tabindex="-1">ulimit：設置核心轉儲的最大尺寸 <a class="header-anchor" href="#ulimit-設置核心轉儲的最大尺寸" aria-label="Permalink to “ulimit：設置核心轉儲的最大尺寸”">​</a></h3><p><code>ulimit -c</code> 設置核心轉儲的最大尺寸。 它往往設置為 0，這意味着內核根本不會寫核心轉儲。 它以千字節為單位。 <code>ulimit</code> 是按每個進程分別設置的 —— 你可以通過運行 <code>cat /proc/PID/limit</code> 看到一個進程的各種資源限制。</p><p>例如這些是我的系統上一個隨便一個 Firefox 進程的資源限制：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /proc/6309/limits </span></span>
<span class="line"><span>Limit                     Soft Limit           Hard Limit           Units     </span></span>
<span class="line"><span>Max cpu time              unlimited            unlimited            seconds   </span></span>
<span class="line"><span>Max file size             unlimited            unlimited            bytes     </span></span>
<span class="line"><span>Max data size             unlimited            unlimited            bytes     </span></span>
<span class="line"><span>Max stack size            8388608              unlimited            bytes     </span></span>
<span class="line"><span>Max core file size        0                    unlimited            bytes     </span></span>
<span class="line"><span>Max resident set          unlimited            unlimited            bytes     </span></span>
<span class="line"><span>Max processes             30571                30571                processes </span></span>
<span class="line"><span>Max open files            1024                 1048576              files     </span></span>
<span class="line"><span>Max locked memory         65536                65536                bytes     </span></span>
<span class="line"><span>Max address space         unlimited            unlimited            bytes     </span></span>
<span class="line"><span>Max file locks            unlimited            unlimited            locks     </span></span>
<span class="line"><span>Max pending signals       30571                30571                signals   </span></span>
<span class="line"><span>Max msgqueue size         819200               819200               bytes     </span></span>
<span class="line"><span>Max nice priority         0                    0                    </span></span>
<span class="line"><span>Max realtime priority     0                    0                    </span></span>
<span class="line"><span>Max realtime timeout      unlimited            unlimited            us</span></span></code></pre></div><p>內核在決定寫入多大的核心轉儲文件時使用<ruby>軟限制<rt>soft limit</rt></ruby>（在這種情況下，<code>max core file size = 0</code>）。 您可以使用 shell 內置命令 <code>ulimit</code>（<code>ulimit -c unlimited</code>） 將軟限制增加到<ruby>硬限制<rt>hard limit</rt></ruby>。</p><h3 id="kernel-core-pattern-核心轉儲保存在哪裏" tabindex="-1">kernel.core_pattern：核心轉儲保存在哪裏 <a class="header-anchor" href="#kernel-core-pattern-核心轉儲保存在哪裏" aria-label="Permalink to “kernel.core_pattern：核心轉儲保存在哪裏”">​</a></h3><p><code>kernel.core_pattern</code> 是一個內核參數，或者叫 “sysctl 設置”，它控制 Linux 內核將核心轉儲文件寫到磁盤的哪裏。</p><p>內核參數是一種設定您的系統全局設置的方法。您可以通過運行 <code>sysctl -a</code> 得到一個包含每個內核參數的列表，或使用 <code>sysctl kernel.core_pattern</code> 來專門查看 <code>kernel.core_pattern</code> 設置。</p><p>所以 <code>sysctl -w kernel.core_pattern=/tmp/core-%e.%p.%h.%t</code> 將核心轉儲保存到目錄 <code>/tmp</code> 下，並以 <code>core</code> 加上一系列能夠標識（出故障的）進程的參數構成的後綴為文件名。</p>`,27)),t("p",null,[e[1]||(e[1]=a("如果你想知道這些形如 ",-1)),e[2]||(e[2]=t("code",null,"%e",-1)),e[3]||(e[3]=a("、",-1)),e[4]||(e[4]=t("code",null,"%p",-1)),e[5]||(e[5]=a(" 的參數都表示什麼，請參考 ",-1)),i(s,{href:"http://man7.org/linux/man-pages/man5/core.5.html"},{default:n(()=>[...e[0]||(e[0]=[a("man core",-1)])]),_:1}),e[6]||(e[6]=a("。",-1))]),e[21]||(e[21]=l(`<p>有一點很重要，<code>kernel.core_pattern</code> 是一個全局設置 —— 修改它的時候最好小心一點，因為有可能其它系統功能依賴於把它被設置為一個特定的方式（才能正常工作）。</p><h3 id="kernel-core-pattern-和-ubuntu" tabindex="-1">kernel.core_pattern 和 Ubuntu <a class="header-anchor" href="#kernel-core-pattern-和-ubuntu" aria-label="Permalink to “kernel.core_pattern 和 Ubuntu”">​</a></h3><p>默認情況下在 ubuntu 系統中，<code>kernel.core_pattern</code> 被設置為下面的值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sysctl kernel.core_pattern</span></span>
<span class="line"><span>kernel.core_pattern = |/usr/share/apport/apport %p %s %c %d %P</span></span></code></pre></div><p>這引起了我的迷惑（這 apport 是幹什麼的，它對我的核心轉儲做了什麼？）。以下關於這個我瞭解到的：</p><ul><li>Ubuntu 使用一種叫做 apport 的系統來報告 apt 包有關的崩潰信息。</li><li>設定 <code>kernel.core_pattern=|/usr/share/apport/apport %p %s %c %d %P</code> 意味着核心轉儲將被通過管道送給 <code>apport</code> 程序。</li><li>apport 的日誌保存在文件 <code>/var/log/apport.log</code> 中。</li><li>apport 默認會忽略來自不屬於 Ubuntu 軟件包一部分的二進制文件的崩潰信息</li></ul><p>我最終只是跳過了 apport，並把 <code>kernel.core_pattern</code> 重新設置為 <code>sysctl -w kernel.core_pattern=/tmp/core-%e.%p.%h.%t</code>，因為我在一台開發機上，我不在乎 apport 是否工作，我也不想嘗試讓 apport 把我的核心轉儲留在磁盤上。</p><h3 id="現在你有了核心轉儲-接下來幹什麼" tabindex="-1">現在你有了核心轉儲，接下來幹什麼？ <a class="header-anchor" href="#現在你有了核心轉儲-接下來幹什麼" aria-label="Permalink to “現在你有了核心轉儲，接下來幹什麼？”">​</a></h3><p>好的，現在我們瞭解了 <code>ulimit</code> 和 <code>kernel.core_pattern</code> ，並且實際上在磁盤的 <code>/tmp</code> 目錄中有了一個核心轉儲文件。太好了！接下來幹什麼？我們仍然不知道該程序為什麼會出現段錯誤！</p><p>下一步將使用 <code>gdb</code> 打開核心轉儲文件並獲取堆棧調用序列。</p><h3 id="從-gdb-中得到堆棧調用序列" tabindex="-1">從 gdb 中得到堆棧調用序列 <a class="header-anchor" href="#從-gdb-中得到堆棧調用序列" aria-label="Permalink to “從 gdb 中得到堆棧調用序列”">​</a></h3><p>你可以像這樣用 <code>gdb</code> 打開一個核心轉儲文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gdb -c my_core_file</span></span></code></pre></div><p>接下來，我們想知道程序崩潰時的堆棧是什麼樣的。在 <code>gdb</code> 提示符下運行 <code>bt</code> 會給你一個<ruby>調用序列<rt>backtrace</rt></ruby>。在我的例子裏，<code>gdb</code> 沒有為二進制文件加載符號信息，所以這些函數名就像 “??????”。幸運的是，（我們通過）加載符號修復了它。</p><p>下面是如何加載調試符號。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>symbol-file /path/to/my/binary</span></span>
<span class="line"><span>sharedlibrary</span></span></code></pre></div><p>這從二進制文件及其引用的任何共享庫中加載符號。一旦我這樣做了，當我執行 <code>bt</code> 時，gdb 給了我一個帶有行號的漂亮的堆棧跟蹤！</p><p>如果你想它能工作，二進制文件應該以帶有調試符號信息的方式被編譯。在試圖找出程序崩潰的原因時，堆棧跟蹤中的行號非常有幫助。😃</p><h3 id="查看每個線程的堆棧" tabindex="-1">查看每個線程的堆棧 <a class="header-anchor" href="#查看每個線程的堆棧" aria-label="Permalink to “查看每個線程的堆棧”">​</a></h3><p>通過以下方式在 <code>gdb</code> 中獲取每個線程的調用棧！</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>thread apply all bt full</span></span></code></pre></div><h3 id="gdb-核心轉儲-驚喜" tabindex="-1">gdb + 核心轉儲 = 驚喜 <a class="header-anchor" href="#gdb-核心轉儲-驚喜" aria-label="Permalink to “gdb + 核心轉儲 = 驚喜”">​</a></h3><p>如果你有一個帶調試符號的核心轉儲以及 <code>gdb</code>，那太棒了！您可以上下查看調用堆棧（LCTT 譯註：指跳進調用序列不同的函數中以便於查看局部變量），打印變量，並查看內存來得知發生了什麼。這是最好的。</p><p>如果您仍然正在基於 gdb 嚮導來工作上，只打印出棧跟蹤與bt也可以。 😃</p><h3 id="asan" tabindex="-1">ASAN <a class="header-anchor" href="#asan" aria-label="Permalink to “ASAN”">​</a></h3><p>另一種搞清楚您的段錯誤的方法是使用 AddressSanitizer 選項編譯程序（“ASAN”，即 <code>$CC -fsanitize=address</code>）然後運行它。 本文中我不準備討論那個，因為本文已經相當長了，並且在我的例子中打開 ASAN 後段錯誤消失了，可能是因為 ASAN 使用了一個不同的內存分配器（系統內存分配器，而不是 tcmalloc）。</p><p>在未來如果我能讓 ASAN 工作，我可能會多寫點有關它的東西。（LCTT 譯註：這裏指使用 ASAN 也能復現段錯誤）</p><h3 id="從一個核心轉儲得到一個堆棧跟蹤真的很親切" tabindex="-1">從一個核心轉儲得到一個堆棧跟蹤真的很親切！ <a class="header-anchor" href="#從一個核心轉儲得到一個堆棧跟蹤真的很親切" aria-label="Permalink to “從一個核心轉儲得到一個堆棧跟蹤真的很親切！”">​</a></h3><p>這個Blog聽起來很多，當我做這些的時候很困惑，但説真的，從一個段錯誤的程序中獲得一個堆棧調用序列不需要那麼多步驟：</p><ol><li>試試用 <code>valgrind</code></li></ol><p>如果那沒用，或者你想要拿到一個核心轉儲來調查：</p><ol><li>確保二進制文件編譯時帶有調試符號信息；</li><li>正確的設置 <code>ulimit</code> 和 <code>kernel.core_pattern</code>；</li><li>運行程序；</li><li>一旦你用 <code>gdb</code> 調試核心轉儲了，加載符號並運行 <code>bt</code>；</li><li>嘗試找出發生了什麼！</li></ol><p>我可以使用 <code>gdb</code> 弄清楚有個 C++ 的虛表條目指向一些被破壞的內存，這有點幫助，並且使我感覺好像更懂了 C++ 一點。也許有一天我們會更多地討論如何使用 <code>gdb</code> 來查找問題！</p><hr>`,34)),t("p",null,[e[8]||(e[8]=a("via: ",-1)),i(s,{href:"https://jvns.ca/blog/2018/04/28/debugging-a-segfault-on-linux/"},{default:n(()=>[...e[7]||(e[7]=[a("https://jvns.ca/blog/2018/04/28/debugging-a-segfault-on-linux/",-1)])]),_:1})]),t("p",null,[e[12]||(e[12]=a("作者：",-1)),i(s,{href:"https://jvns.ca/about/"},{default:n(()=>[...e[9]||(e[9]=[a("Julia Evans",-1)])]),_:1}),e[13]||(e[13]=a(" 譯者：",-1)),i(s,{href:"https://github.com/stephenxs"},{default:n(()=>[...e[10]||(e[10]=[a("stephenxs",-1)])]),_:1}),e[14]||(e[14]=a(" 校對：",-1)),i(s,{href:"https://github.com/wxy"},{default:n(()=>[...e[11]||(e[11]=[a("wxy",-1)])]),_:1})]),t("p",null,[e[17]||(e[17]=a("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[15]||(e[15]=[a("LCTT",-1)])]),_:1}),e[18]||(e[18]=a(" 原創編譯，",-1)),i(s,{href:"https://linux.cn/"},{default:n(()=>[...e[16]||(e[16]=[a("Linux中國",-1)])]),_:1}),e[19]||(e[19]=a(" 榮譽推出",-1))])])}const C=p(c,[["render",u]]);export{y as __pageData,C as default};
